import { defineComponent, h, shallowRef, type PropType, type VNode } from 'vue';
import { buildSonnerToastApi, createSonnerStore, getSonnerPositionStyleKeys, sonnerStyleKeys } from '../lib/core';
import type { SonnerPosition, SonnerToast, SonnerType } from '../lib/core';
import styles from './sonner.module.scss';

const sonnerStore = createSonnerStore();

const toasts = shallowRef<SonnerToast[]>(sonnerStore.getToasts());
sonnerStore.subscribe(() => {
	toasts.value = sonnerStore.getToasts();
});

export const toast = buildSonnerToastApi(sonnerStore);

export function useToast() {
	return {
		toasts,
		toast,
		dismiss: (id?: string) => toast.dismiss(id),
		dismissAll: () => toast.dismissAll(),
	};
}

function svgAttrs() {
	return {
		xmlns: 'http://www.w3.org/2000/svg',
		width: '16',
		height: '16',
		viewBox: '0 0 24 24',
		fill: 'none',
		stroke: 'currentColor',
		'stroke-width': '2',
		'stroke-linecap': 'round',
		'stroke-linejoin': 'round',
		'aria-hidden': 'true',
	};
}

function renderToastIcon(type: SonnerType) {
	switch (type) {
		case 'success':
			return h('svg', svgAttrs(), [h('circle', { cx: '12', cy: '12', r: '10' }), h('path', { d: 'm9 12 2 2 4-4' })]);
		case 'info':
			return h('svg', svgAttrs(), [h('circle', { cx: '12', cy: '12', r: '10' }), h('path', { d: 'M12 16v-4' }), h('path', { d: 'M12 8h.01' })]);
		case 'warning':
			return h('svg', svgAttrs(), [
				h('path', { d: 'm21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z' }),
				h('path', { d: 'M12 9v4' }),
				h('path', { d: 'M12 17h.01' }),
			]);
		case 'error':
			return h('svg', svgAttrs(), [h('path', { d: 'M13 2 3 14h9l-1 8 10-12h-9l1-8Z' })]);
		case 'loading':
			return h('svg', svgAttrs(), [h('path', { d: 'M21 12a9 9 0 1 1-6.219-8.56' })]);
		default:
			return null;
	}
}

const closeIcon = h('svg', svgAttrs(), [h('path', { d: 'M18 6 6 18' }), h('path', { d: 'm6 6 12 12' })]);

export const TToaster = defineComponent({
	name: 'TToaster',
	props: {
		position: { type: String as PropType<SonnerPosition>, default: 'bottom-right' },
		closeButton: { type: Boolean, default: true },
	},
	setup(props) {
		return () => {
			const groups = new Map<string, SonnerToast[]>();
			for (const item of toasts.value) {
				const key = item.position ?? props.position;
				const list = groups.get(key);
				if (list) {
					list.push(item);
				} else {
					groups.set(key, [item]);
				}
			}

			const containers: VNode[] = [];
			for (const [groupPosition, list] of groups) {
				const styleKeys = getSonnerPositionStyleKeys(groupPosition as SonnerPosition);
				const toastNodes = list.map((item) => {
					const children: VNode[] = [];
					const icon = renderToastIcon(item.type);
					if (icon) {
						children.push(h('div', { class: styles[sonnerStyleKeys.icon] }, [icon]));
					}
					children.push(
						h('div', { class: styles[sonnerStyleKeys.content] }, [
							item.title !== undefined ? h('div', { class: styles[sonnerStyleKeys.title] }, item.title) : null,
							item.description !== undefined ? h('div', { class: styles[sonnerStyleKeys.description] }, item.description) : null,
						]),
					);
					if (props.closeButton && item.dismissible !== false) {
						children.push(
							h('button', { type: 'button', 'aria-label': '关闭', class: styles[sonnerStyleKeys.close], onClick: () => sonnerStore.dismiss(item.id) }, [closeIcon]),
						);
					}
					return h(
						'div',
						{ key: item.id, 'data-slot': 'toast', 'data-type': item.type, 'data-dismissing': item.dismissing ? 'true' : 'false', class: styles[sonnerStyleKeys.toast] },
						children,
					);
				});
				containers.push(h('div', { key: groupPosition, 'data-slot': 'toaster', class: [styles[styleKeys.base], styles[styleKeys.position]] }, toastNodes));
			}
			return containers;
		};
	},
});

export default TToaster;

@use '../../../styles/variables/colors' as *;

// Toaster 容器
.root {
	position: fixed;
	z-index: $z-modal;
	display: flex;
	flex-direction: column;
	gap: $spacing-2;
	width: max-content;
	max-width: calc(100vw - 2rem);
	pointer-events: none;

	&.positionTopLeft {
		top: $spacing-4;
		left: $spacing-4;
	}

	&.positionTopRight {
		top: $spacing-4;
		right: $spacing-4;
	}

	&.positionTopCenter {
		top: $spacing-4;
		left: 50%;
		transform: translateX(-50%);
	}

	&.positionBottomLeft {
		bottom: $spacing-4;
		left: $spacing-4;
	}

	&.positionBottomRight {
		right: $spacing-4;
		bottom: $spacing-4;
	}

	&.positionBottomCenter {
		bottom: $spacing-4;
		left: 50%;
		transform: translateX(-50%);
	}
}

// 单条提示
.toast {
	display: flex;
	align-items: center;
	gap: $spacing-3;
	min-width: 0;
	border: 1px solid $border;
	border-radius: $radius;
	background-color: $popover;
	color: $popover-foreground;
	padding: $spacing-3 $spacing-4;
	box-shadow: $shadow-md;
	pointer-events: auto;
	transition:
		opacity $transition-normal,
		transform $transition-normal;

	&[data-dismissing='true'] {
		opacity: 0;
		transform: translateY(0.5rem);
	}
}

// 图标
.icon {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	width: $spacing-5;
	height: $spacing-5;

	svg {
		width: $spacing-4;
		height: $spacing-4;
	}

	.toast[data-type='success'] & {
		color: $success;
	}

	.toast[data-type='info'] & {
		color: $info;
	}

	.toast[data-type='warning'] & {
		color: $warning;
	}

	.toast[data-type='error'] & {
		color: $destructive;
	}
}

// 内容
.content {
	display: flex;
	min-width: 0;
	flex: 1;
	flex-direction: column;
}

// 标题
.title {
	font-size: $text-sm;
	font-weight: $font-medium;
	line-height: $leading-tight;
}

// 描述
.description {
	margin-top: 0.125rem;
	font-size: $text-sm;
	color: $muted-foreground;
	line-height: $leading-normal;
}

// 关闭按钮
.close {
	display: inline-flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	border: none;
	border-radius: $radius;
	background: transparent;
	color: $muted-foreground;
	cursor: pointer;
	padding: $spacing-1;
	transition:
		background-color $transition-fast,
		color $transition-fast;

	&:hover {
		background-color: $muted;
		color: $foreground;
	}

	svg {
		width: $spacing-4;
		height: $spacing-4;
	}
}

// 操作按钮容器
.actions {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	gap: $spacing-1;
}
